import React, { useState, useEffect } from 'react';
import { GoogleGenerativeAI } from "@google/generative-ai";

const GEMINI_API_KEY = "AIzaSyAycjPVxkbcJFfOSJyTp8oBUsONgK7lY1k"; 

function App() {
  const [mekanlar, setMekanlar] = useState([]);
  const [favoriler, setFavoriler] = useState([]);
  const [seciliMekanId, setSeciliMekanId] = useState(null);
  const [veriYukleniyor, setVeriYukleniyor] = useState(true);

  // 🌍 DİL AYARLARI (Varsayılan TR)
  const [dil, setDil] = useState('tr'); 

  const [muzekartVar, setMuzekartVar] = useState(false);
  const [aiBilgi, setAiBilgi] = useState({ cevap: "", temp: "", durum: "" });
  const [loading, setLoading] = useState(false);

  // 📖 SABİT METİNLER SÖZLÜĞÜ
  const texts = {
    tr: {
      title: "ANTALYA ROTA ASİSTANI",
      muzekartVar: "💳 Müzekart Var",
      muzekartYok: "💳 Müzekart Yok",
      mekanSecildi: "Mekan Seçildi",
      rotaOlustur: "Rotayı Çiz 🚀",
      ucretsiz: "ÜCRETSİZ",
      aiIpucu: "✨ AI İpucu",
      ekle: "Ekle +",
      cikar: "Çıkar",
      aiLoading: "Zeka düşünüyor...",
      aiError: "Bağlantı sorunu var ama manzara harika!",
      kategoriler: { Tarih: "Tarih Rotaları", Doğa: "Doğa Rotaları", Eğlence: "Eğlence Rotaları", Yemek: "Lezzet Durakları" }
    },
    en: {
      title: "ANTALYA ROUTE ASSISTANT",
      muzekartVar: "💳 Museum Pass: Yes",
      muzekartYok: "💳 Museum Pass: No",
      mekanSecildi: "Places Selected",
      rotaOlustur: "Create Route 🚀",
      ucretsiz: "FREE",
      aiIpucu: "✨ AI Tip",
      ekle: "Add +",
      cikar: "Remove",
      aiLoading: "Thinking...",
      aiError: "Connection issue, but enjoy the view!",
      kategoriler: { Tarih: "Historical Routes", Doğa: "Nature Routes", Eğlence: "Entertainment", Yemek: "Gourmet Stops" }
    },
    ru: {
      title: "МАРШРУТ АНТАЛЬИ",
      muzekartVar: "💳 Музейная карта: Есть",
      muzekartYok: "💳 Музейная карта: Нет",
      mekanSecildi: "Выбрано мест",
      rotaOlustur: "Создать маршрут 🚀",
      ucretsiz: "БЕСПЛАТНО",
      aiIpucu: "✨ AI Совет",
      ekle: "Добавить +",
      cikar: "Убрать",
      aiLoading: "Думаю...",
      aiError: "Проблема с подключением, но вид отличный!",
      kategoriler: { Tarih: "Исторические", Doğa: "Природа", Eğlence: "Развлечения", Yemek: "Еда" }
    }
  };

  const t = texts[dil]; // Seçili dile göre metinleri al

  useEffect(() => {
    fetch('http://localhost:5000/api/rota')
      .then(res => res.json())
      .then(data => {
        setMekanlar(data);
        setVeriYukleniyor(false);
      })
      .catch(err => setVeriYukleniyor(false));
  }, []);

  const kategoriler = {
    "Tarih": mekanlar.filter(m => m.kategori === "Tarih"),
    "Doğa": mekanlar.filter(m => m.kategori === "Doğa"),
    "Eğlence": mekanlar.filter(m => m.kategori === "Eğlence"),
    "Yemek": mekanlar.filter(m => m.kategori === "Yemek"),
  };

  const kategoriArkaPlanlari = {
    "Tarih": "https://images.unsplash.com/photo-1528164344705-475426870763?q=80&w=2070&auto=format&fit=crop", 
    "Doğa": "https://images.unsplash.com/photo-1433838552652-f9a46b332c40?q=80&w=2070&auto=format&fit=crop", 
    "Eğlence": "https://images.unsplash.com/photo-1566737236500-c8ac43014a67?q=80&w=2070&auto=format&fit=crop", 
    "Yemek": "https://images.unsplash.com/photo-1555396273-367ea4eb4db5?q=80&w=1974&auto=format&fit=crop", 
  };

  const rotayiHaritadaGoster = () => {
    if (favoriler.length === 0) return alert("Listeniz boş!");
    // Haritada her zaman Türkçe isimleri kullanalım ki Google Maps şaşırmasın
    const duraklar = favoriler.map(m => encodeURIComponent(m.ad.tr)).join('/');
    window.open(`https://www.google.com/maps/dir/Current+Location/${duraklar}`, '_blank');
  };

  const toggleFavori = (mekan) => {
    const varMi = favoriler.find(f => f.id === mekan.id);
    if (varMi) setFavoriler(favoriler.filter(f => f.id !== mekan.id));
    else setFavoriler([...favoriler, mekan]);
  };

  const askSmartAI = async (mekan) => {
    if (seciliMekanId === mekan.id) { setSeciliMekanId(null); return; }

    setSeciliMekanId(mekan.id);
    setLoading(true);
    setAiBilgi({ cevap: "", temp: "", durum: "" });

    try {
      const wRes = await fetch(`http://localhost:5000/api/hava-durumu?lat=${mekan.lat}&lon=${mekan.lon}`);
      const wData = await wRes.json(); 

      const genAI = new GoogleGenerativeAI(GEMINI_API_KEY);
      const model = genAI.getGenerativeModel({ model: "gemini-1.5-flash" });

      // 🤖 PROMPT'U DİLE GÖRE AYARLIYORUZ
      let promptText = "";
      if (dil === 'tr') promptText = `Antalya ${mekan.ad.tr} konumundayım. Hava ${wData.sicaklik}°C. Turist rehberi gibi kısa, samimi bir ipucu ver. Türkçe cevapla.`;
      if (dil === 'en') promptText = `I am at ${mekan.ad.en} in Antalya. Weather is ${wData.sicaklik}°C. Give me a short, friendly tourist guide tip. Answer in English.`;
      if (dil === 'ru') promptText = `Я в ${mekan.ad.ru}, Анталья. Погода ${wData.sicaklik}°C. Дай мне короткий, дружелюбный совет гида. Ответь на русском.`;

      const result = await model.generateContent(promptText);

      setAiBilgi({ 
          cevap: result.response.text(), 
          temp: wData.sicaklik, 
          durum: wData.durum 
      });

    } catch (err) {
      setAiBilgi({ cevap: t.aiError, temp: "--", durum: "?" });
    } finally { 
      setLoading(false); 
    }
  };

  if (veriYukleniyor) return <div style={{display:'flex', justifyContent:'center', alignItems:'center', height:'100vh', background:'#111827', color:'#38bdf8', fontSize:'20px'}}>Loading...</div>;

  return (
    <div style={{ fontFamily: "'Poppins', sans-serif", background: '#000' }}>
      <style>{`
        body { margin: 0; padding: 0; color: #e2e8f0; }
        * { box-sizing: border-box; }
        .navbar { 
            display: flex; justify-content: space-between; align-items: center; 
            padding: 15px 40px; 
            background: rgba(0, 0, 0, 0.8); 
            backdrop-filter: blur(15px);
            position: sticky; top: 0; z-index: 1000;
            border-bottom: 1px solid rgba(255,255,255,0.1);
        }
        .category-section {
            min-height: 100vh; padding: 60px 40px;
            background-attachment: fixed; background-size: cover;
            display: flex; flex-direction: column; justify-content: center; position: relative;
        }
        .overlay { position: absolute; top: 0; left: 0; width: 100%; height: 100%; background: rgba(0, 0, 0, 0.75); z-index: 1; }
        .section-content { position: relative; z-index: 2; }
        .category-title { font-size: 40px; font-weight: 800; color: #f8fafc; margin-bottom: 30px; border-left: 6px solid #f97316; padding-left: 20px; }
        .grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(320px, 1fr)); gap: 30px; }
        .card { background: rgba(30, 41, 59, 0.85); backdrop-filter: blur(5px); border-radius: 20px; overflow: hidden; border: 1px solid rgba(255, 255, 255, 0.1); transition: all 0.4s ease; display: flex; flex-direction: column; }
        .card:hover { transform: translateY(-10px); border-color: #f97316; }
        .img-container { height: 200px; }
        .card-img { width: 100%; height: 100%; object-fit: cover; }
        .btn-gradient { background: linear-gradient(135deg, #f97316 0%, #fb923c 100%); color: white; border: none; padding: 10px 25px; border-radius: 50px; font-weight: bold; cursor: pointer; }
        .muzekart-btn { background: rgba(255,255,255,0.1); color: white; border: 1px solid rgba(255,255,255,0.2); padding: 8px 16px; border-radius: 8px; cursor: pointer; }
        .lang-btn { font-size: 24px; background: transparent; border: none; cursor: pointer; opacity: 0.5; transition: 0.3s; }
        .lang-btn.active { opacity: 1; transform: scale(1.2); }
      `}</style>

      {/* Navbar */}
      <nav className="navbar">
        <div style={{ display:'flex', alignItems:'center', gap:'10px' }}>
            <span style={{fontSize:'28px'}}>🏝️</span>
            <div>
                <div style={{ fontWeight: 800, color: '#38bdf8', fontSize: '18px' }}>ANTALYA</div>
                <div style={{ fontWeight: 400, color: '#f97316', fontSize: '11px', letterSpacing:'1px' }}>{t.title}</div>
            </div>
        </div>

        {/* 🌍 DİL SEÇİM BUTONLARI */}
        <div style={{display:'flex', gap:'10px'}}>
            <button onClick={() => setDil('tr')} className={`lang-btn ${dil === 'tr' ? 'active' : ''}`}>🇹🇷</button>
            <button onClick={() => setDil('en')} className={`lang-btn ${dil === 'en' ? 'active' : ''}`}>🇬🇧</button>
            <button onClick={() => setDil('ru')} className={`lang-btn ${dil === 'ru' ? 'active' : ''}`}>🇷🇺</button>
        </div>

        <div style={{ display: 'flex', gap: '20px', alignItems: 'center' }}>
            <button onClick={() => setMuzekartVar(!muzekartVar)} className="muzekart-btn" style={{background: muzekartVar ? '#4f46e5' : 'transparent'}}>
              {muzekartVar ? t.muzekartVar : t.muzekartYok}
            </button>
            <div style={{fontWeight:'700', color:'#f97316'}}>
               {favoriler.length > 0 ? `${favoriler.length} ${t.mekanSecildi}` : ""}
            </div>
            <button onClick={rotayiHaritadaGoster} className="btn-gradient">
                {t.rotaOlustur}
            </button>
        </div>
      </nav>

      {/* ROTA LİSTESİ */}
      {Object.keys(kategoriler).map((katAdi) => {
          const mekanListesi = kategoriler[katAdi];
          if (mekanListesi.length === 0) return null;

          return (
            <div key={katAdi} className="category-section" style={{ backgroundImage: `url(${kategoriArkaPlanlari[katAdi] || kategoriArkaPlanlari["Doğa"]})` }}>
                <div className="overlay"></div>
                <div className="section-content">
                    {/* Başlığı seçili dile göre sözlükten al */}
                    <h2 className="category-title">{t.kategoriler[katAdi]}</h2>
                    <div className="grid">
                        {mekanListesi.map(m => {
                            const favorideMi = favoriler.some(f => f.id === m.id);
                            const ucret = (muzekartVar && m.kategori === 'Tarih') ? 0 : parseInt(m.ucret);

                            return (
                                <div key={m.id} className="card">
                                    <div className="img-container">
                                        <img src={m.resim} className="card-img" alt={m.ad[dil]} />
                                    </div>
                                    <div style={{ padding: '20px', display:'flex', flexDirection:'column', flex:1 }}>
                                        <div style={{display:'flex', justifyContent:'space-between', alignItems:'center', marginBottom:'10px'}}>
                                            {/* 🌍 DİNAMİK İSİM: m.ad[dil] */}
                                            <h3 style={{margin:0, color:'#f1f5f9'}}>{m.ad[dil]}</h3>
                                            <span style={{color: ucret === 0 ? '#4ade80' : '#f97316', fontWeight:'bold'}}>
                                                {ucret === 0 ? t.ucretsiz : `${ucret} ₺`}
                                            </span>
                                        </div>
                                        {/* 🌍 DİNAMİK AÇIKLAMA: m.aciklama[dil] */}
                                        <p style={{fontSize:'13px', color:'#94a3b8', flex:1}}>{m.aciklama[dil]}</p>

                                        <div style={{ display: 'flex', gap: '10px', marginTop:'15px' }}>
                                            <button onClick={() => askSmartAI(m)} style={{flex:1, padding:'10px', borderRadius:'8px', border:'none', background:'#334155', color:'#38bdf8', cursor:'pointer', fontWeight:'bold'}}>
                                                {t.aiIpucu}
                                            </button>
                                            <button onClick={() => toggleFavori(m)} style={{flex:1, padding:'10px', borderRadius:'8px', border:'none', background: favorideMi ? '#ef4444' : '#0f766e', color:'white', cursor:'pointer', fontWeight:'bold'}}>
                                                {favorideMi ? t.cikar : t.ekle}
                                            </button>
                                        </div>
                                        {seciliMekanId === m.id && (
                                            <div style={{marginTop:'15px', padding:'10px', background:'rgba(0,0,0,0.3)', borderRadius:'10px', borderLeft:'3px solid #38bdf8', fontSize:'13px', color:'#e2e8f0'}}>
                                                {loading ? t.aiLoading : (
                                                    <div>
                                                        <div style={{marginBottom:'5px', color: '#fbbf24'}}>🌡️ {aiBilgi.temp}°C - {aiBilgi.durum}</div>
                                                        {aiBilgi.cevap}
                                                    </div>
                                                )}
                                            </div>
                                        )}
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                </div>
            </div>
          );
      })}
    </div>
  );
}

export default App;
